:root {
  color-scheme: light;
  --background: #ffffff;
  --foreground: #222222;
  --card: #ffffff;
  --primary: #ff385c;
  --primary-active: #e00b41;
  --primary-disabled: #ffd1da;
  --muted: #f7f7f7;
  --surface-strong: #f2f2f2;
  --body: #3f3f3f;
  --muted-foreground: #6a6a6a;
  --muted-soft: #929292;
  --border: #dddddd;
  --hairline-soft: #ebebeb;
  --border-strong: #c1c1c1;
  --destructive: #c13515;
  --legal-link: #428bff;
  --scrim: rgb(0 0 0 / 50%);
  --radius: 14px;
  --elevation-float:
    0 0 0 1px rgb(0 0 0 / 2%), 0 2px 6px rgb(0 0 0 / 4%),
    0 4px 8px rgb(0 0 0 / 10%);
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
    line-height: 1.5;
  }
  html {
    scroll-behavior: smooth;
  }
  a,
  button,
  input,
  select,
  textarea {
    touch-action: manipulation;
  }
  button:not(:disabled),
  [role="button"]:not([aria-disabled="true"]) {
    cursor: pointer;
  }
  a:focus-visible,
  button:focus-visible {
    outline: 2px solid var(--foreground);
    outline-offset: 4px;
  }
  section[id] {
    scroll-margin-top: 112px;
  }
  ::selection {
    background: var(--primary-disabled);
    color: var(--foreground);
  }
}

@layer components {
  .section-heading {
    @apply text-heading text-balance;
  }
  .section-copy {
    @apply text-pretty text-sm leading-relaxed text-muted-foreground;
  }
  .spec-panel {
    @apply rounded-md border border-border bg-background text-foreground;
  }
  .nav-link {
    @apply flex min-h-11 items-center gap-3 rounded-sm px-3 text-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground;
  }
  .nav-link[aria-current="location"] {
    @apply bg-primary/5 text-primary-active font-medium;
  }
  .source-code {
    @apply min-w-0 overflow-x-auto rounded-sm bg-muted p-4 font-mono text-sm leading-relaxed text-foreground;
  }
  .search-field {
    @apply transition-colors focus-within:bg-muted has-[:focus-visible]:outline-2 has-[:focus-visible]:-outline-offset-2 has-[:focus-visible]:outline-foreground;
  }
  .search-field > label {
    line-height: 20px;
  }
  @media (hover: hover) {
    .search-bar:not(:focus-within) .search-field:hover {
      background: var(--muted);
    }
    .search-bar:not(:focus-within) .search-field:hover::before,
    .search-bar:not(:focus-within) .search-field:hover + .search-field::before {
      opacity: 0;
    }
  }
  .search-field + .search-field::before {
    content: "";
    position: absolute;
    inset-block: 16px;
    inset-inline-start: 0;
    width: 1px;
    background: var(--border);
  }
  .search-field:focus-within::before,
  .search-field:focus-within + .search-field::before {
    opacity: 0;
  }
  .search-control {
    @apply h-6 w-full min-w-0 appearance-none border-0 bg-transparent p-0 text-sm leading-6 text-foreground outline-none placeholder:text-muted-foreground;
  }
  .search-control[type="date"] {
    position: static;
    padding-inline-end: 24px;
  }
  .search-control::-webkit-datetime-edit,
  .search-control::-webkit-datetime-edit-text,
  .search-control::-webkit-datetime-edit-fields-wrapper,
  .search-control::-webkit-datetime-edit-year-field,
  .search-control::-webkit-datetime-edit-month-field,
  .search-control::-webkit-datetime-edit-day-field,
  .search-control::-webkit-date-and-time-value {
    padding: 0;
    text-align: start;
  }
  .search-control::-webkit-calendar-picker-indicator {
    position: absolute;
    inset-inline-end: 24px;
    top: 50%;
    transform: translateY(-50%);
    cursor: pointer;
    width: 16px;
    height: 16px;
    margin: 0;
    padding: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
